  for(let b=0;b<3;b++){
   temp.position.set(x,Math.max(7,h*(.65+b*.1)),z);
   temp.rotation.set((rand()-.5)*1.4,rand()*6.28,(rand()-.5)*1.4);
   temp.scale.set(1,2+rand()*2,1);temp.updateMatrix();branches.setMatrixAt(bc++,temp.matrix);
  }
