// User-supplied MusMus soundtrack: one decoded buffer, one active loop, no network.
function chaseGainForDistance(distance){
 const proximity=clamp((32-distance)/29,0,1);
 return .75*proximity*proximity*(3-2*proximity);
}
const chaseMusic={
 ctx:null,gain:null,buffer:null,source:null,loading:null,error:false,
 offset:0,startedAt:0,target:0,
 prepare(ctx,master){
  if(this.loading||this.buffer||this.error)return;
  this.ctx=ctx;this.gain=ctx.createGain();this.gain.gain.value=0;this.gain.connect(master);
  $('bgm-status').textContent='追跡BGMを準備しています…';
  try{
   const bytes=Uint8Array.from(atob(CHASE_BGM),c=>c.charCodeAt(0));
   this.loading=ctx.decodeAudioData(bytes.buffer).then(buffer=>{
    this.buffer=buffer;
    $('bgm-status').textContent='追跡BGMは、敵が近いほど大きくなります。';
    this.sync();
   }).catch(()=>this.fail());
  }catch(e){this.fail();}
 },
 fail(){
  this.error=true;this.stop(true);
  $('bgm-status').textContent='BGMを再生できませんでした。ブラウザを更新して再読み込みしてください。';
  if(state==='playing')toast('BGMの読み込みに失敗しました。効果音のみで続行します。',6);
 },
 start(){
  if(this.source||!this.buffer||!this.ctx||this.ctx.state!=='running')return;
  const source=this.ctx.createBufferSource();source.buffer=this.buffer;source.loop=true;
  source.connect(this.gain);this.startedAt=this.ctx.currentTime;this.source=source;
  source.start(0,this.offset%this.buffer.duration);
 },
 stop(reset=false){
  if(this.source){
   if(this.buffer)this.offset=(this.offset+this.ctx.currentTime-this.startedAt)%this.buffer.duration;
   this.source.stop();this.source.disconnect();this.source=null;
  }
  if(reset)this.offset=0;
  this.target=0;
  if(this.gain){this.gain.gain.cancelScheduledValues(0);this.gain.gain.setValueAtTime(0,this.ctx.currentTime);}
 },
 sync(){
  // Pause/mute preserve position; title, defeat, escape and retry reset the track.
  if(state!=='playing'){this.stop(state!=='paused');return;}
  if(settings.muted||settings.volume===0){this.stop(false);return;}
  if(!this.buffer||!this.gain||this.ctx.state!=='running')return;
  const distance=Math.hypot(player.x-enemy.x,player.z-enemy.z);
  const next=chaseGainForDistance(distance);
  if(next>0&&!this.source)this.start();
  if(Math.abs(next-this.target)>.001||(next===0&&this.target!==0)){
   // Web Audio gain, rather than HTMLMediaElement.volume, also works on iOS.
   this.gain.gain.setTargetAtTime(next,this.ctx.currentTime,next>this.target?.28:.5);
   this.target=next;
  }
  if(next===0&&this.source&&this.gain.gain.value<.001)this.stop(false);
 }
};
function applySettings(){for(const k of ['volume','sensitivity','brightness','quality'])$(k).value=settings[k];$('gentle').setAttribute('aria-checked',String(settings.gentle));$('home-sound').innerHTML='<svg><use href="#i-'+(settings.muted?'mute':'sound')+'"/></svg><span>SOUND '+(settings.muted?'OFF':'ON')+'</span>';if(renderer){renderer.toneMappingExposure=settings.brightness/100*(state==='home'?1.18:1.02);resize();}audio.update();saveSettings();}
function resetInput(){Object.keys(keys).forEach(k=>delete keys[k]);input.moveId=null;input.lookId=null;input.mx=input.my=0;runHeld=false;$('run').classList.remove('active');$('joystick').style.display='none';}
function toast(message,time=4){$('toast').textContent=message;$('toast').classList.add('visible');toastTime=time;}
function formatTime(seconds){return String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(Math.floor(seconds%60)).padStart(2,'0');}
function updateHUD(){ $('part-count').textContent=partsFound;document.querySelectorAll('.part-dot').forEach((e,i)=>e.classList.toggle('found',i<partsFound));$('mission-hint').textContent=partsFound===7?'入口の封鎖を解き、バイクへ戻る':'光る部品を探し、バイクへ戻る';}
function startGame(){if(!ready)return;chaseMusic.stop(true);for(const id of ['home','gameover','victory','scare','pause-modal','help-modal','settings-modal'])hide(id);show('hud');layoutHud();state='playing';elapsed=0;partsFound=0;stamina=100;exhausted=false;yaw=0;pitch=0;player.x=0;player.z=26;enemy.x=0;enemy.z=-8;enemy.path=[];enemy.repath=0;flashOn=true;flash.visible=true;enemyMesh.visible=true;$('light').classList.add('active');for(const p of parts){p.found=false;p.group.visible=true;}resetInput();lastBeat=lastStep=walkPhase=0;updateHUD();audio.init();applySettings();toast('7つの部品を探そう。帰り道は、南の鳥居。',6);$('touch-hints').style.opacity=touchDevice?1:0;clock.getDelta();document.activeElement?.blur();}
function returnHome(){state='home';resetInput();for(const id of ['hud','gameover','victory','scare','pause-modal','help-modal','settings-modal'])hide(id);show('home');$('danger').style.opacity=0;for(const p of parts)p.group.visible=true;audio.update();applySettings();$('start').focus({preventScroll:true});}
function pauseGame(){if(state!=='playing')return;state='paused';resetInput();$('pause-time').textContent=formatTime(elapsed);$('pause-parts').textContent='PARTS '+partsFound+' / 7';show('pause-modal');audio.update();$('resume').focus();}
function resumeGame(){hide('pause-modal');hide('help-modal');hide('settings-modal');state='playing';resetInput();audio.init();clock.getDelta();document.activeElement?.blur();}
function openModal(id){lastFocus=document.activeElement;modalReturn=state;if(state==='playing'){state='paused';resetInput();audio.update();}hide('pause-modal');show(id);$(id).querySelector('button,input,select')?.focus();}
function closeModal(id){hide(id);if(modalReturn==='playing')resumeGame();else if(modalReturn==='paused'){show('pause-modal');$('resume').focus();}else lastFocus?.focus();}
function endGame(won){if(state!=='playing')return;state=won?'won':'dying';resetInput();hide('hud');$('danger').style.opacity=0;audio.update();if(won){show('victory');$('win-summary').textContent='部品 7 / 7 回収　 ·　生還タイム '+formatTime(elapsed);let best=elapsed;try{const old=Number(localStorage.getItem('mayoi.best.world-v3'));best=old>0?Math.min(old,elapsed):elapsed;localStorage.setItem('mayoi.best.world-v3',String(best));}catch(e){}$('best-time').textContent='BEST RECORD — '+formatTime(best);audio.tone(220,1,.12,'sine',440);$('replay').focus();}else{audio.scare();if(!settings.gentle)show('scare');deathDelay=settings.gentle?.15:.65;}}
function revealGameOver(){hide('scare');show('gameover');state='dead';$('death-summary').textContent='探索時間 '+formatTime(elapsed)+'　 ·　回収した部品 '+partsFound+' / 7';$('retry').focus();}
function getInteraction(){for(const p of parts)if(!p.found&&Math.hypot(player.x-p.x,player.z-p.z)<2.6)return {type:'part',p};if(Math.hypot(player.x,player.z-30)<3.1)return {type:'bike'};return null;}
function interact(){if(state!=='playing')return;const hit=getInteraction();if(!hit)return;if(hit.type==='part'){hit.p.found=true;hit.p.group.visible=false;partsFound++;audio.pickup();updateHUD();toast(hit.p.name+' を手に入れた。'+(partsFound===7?'入口の封鎖を解き、バイクへ戻ろう。':''),4);if(partsFound===1)enemy.repath=0;}else if(partsFound===7)endGame(true);else toast('バイクを動かすには、あと'+(7-partsFound)+'つの部品が必要。');}
function toggleLight(){flashOn=!flashOn;if(flash)flash.visible=flashOn;$('light').classList.toggle('active',flashOn);}
function updatePlayer(dt){let mx=input.mx+(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0),my=input.my+(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0);const len=Math.hypot(mx,my);if(len>1){mx/=len;my/=len;}const moving=len>.06,running=moving&&(runHeld||keys.ShiftLeft||keys.ShiftRight)&&!exhausted&&stamina>1;if(running){stamina=Math.max(0,stamina-dt*21);if(stamina<1)exhausted=true;}else{stamina=Math.min(100,stamina+dt*13);if(stamina>25)exhausted=false;}const speed=running?5.5:3.25;if(moving){const dx=(mx*Math.cos(yaw)+my*Math.sin(yaw))*speed*dt,dz=(-mx*Math.sin(yaw)+my*Math.cos(yaw))*speed*dt;moveEntity(player,dx,dz);walkPhase+=dt*(running?13:8);if(elapsed-lastStep>(running?.32:.48)){lastStep=elapsed;audio.step(running);}}camera.position.set(player.x,1.7+(moving&&!settings.gentle?Math.sin(walkPhase)*.035:0),player.z);camera.rotation.set(pitch,yaw,0);flash.position.copy(camera.position);camera.getWorldDirection(V);flashTarget.position.copy(camera.position).addScaledVector(V,12);flash.visible=flashOn;$('stamina').style.width=stamina+'%';$('stamina').style.background=exhausted?'#b76c56':'#bac59b';
 const deg=(((-yaw*180/Math.PI)%360)+360)%360;const headings=['N','NE','E','SE','S','SW','W','NW'];$('compass-heading').textContent=headings[Math.round(deg/45)%8]+' · '+String(Math.round(deg)).padStart(3,'0')+'°';const hit=getInteraction();if(hit){show('interaction');$('interaction').textContent=hit.type==='part'?hit.p.name+' を拾う':partsFound===7?'バイクで脱出する':'バイクを調べる';}else hide('interaction');if(toastTime>0){toastTime-=dt;if(toastTime<=0)$('toast').classList.remove('visible');}if(elapsed>14)$('touch-hints').style.opacity=0;}
function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.05);ambientTime+=dt;frameCount++;if(state==='playing'){elapsed+=dt;updatePlayer(dt);updateEnemy(dt);}else if(state==='escaping'){world.escape(dt);}else if(state==='home'){camera.position.set(9.5,2.2,22);camera.rotation.set(.015,-.06+Math.sin(ambientTime*.09)*.045,0);flash.visible=false;enemyMesh.visible=false;}else if(state==='dying'){deathDelay-=dt;if(deathDelay<=0)revealGameOver();}
 if(state!=='paused'){for(let i=0;i<parts.length;i++){const p=parts[i];if(!p.found){p.group.rotation.y=i*1.7;p.group.position.y=(world?world.map.floor(p.x,p.z):0)+.42;}}fireflies.rotation.y=Math.sin(ambientTime*.03)*.015;}if(naturalForest)naturalForest.update();if(state!=='paused'||frameCount%12===0)renderer.render(scene,camera);}

const EXTRA_FACES=["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/png;base64,"];
/* Classic forest edition: the original world, UI, controls and AI are retained. */
class SpawnManager {
 constructor(){this.reachable=[];this.candidates=[];this.build();}
 build(){buildNav();const start=freeCell(cellOf(0,26)),seen=new Set([start]),queue=[start];const point=id=>({x:ORIGIN+(id%GRID)*CELL,z:ORIGIN+Math.floor(id/GRID)*CELL});for(let i=0;i<queue.length;i++){const id=queue[i],x=id%GRID,z=Math.floor(id/GRID),a=point(id);for(const [dx,dz]of [[1,0],[-1,0],[0,1],[0,-1]]){const nx=x+dx,nz=z+dz,n=nz*GRID+nx;if(nx<0||nz<0||nx>=GRID||nz>=GRID||nav[n]||seen.has(n))continue;const b=point(n);if(!clearLine(a.x,a.z,b.x,b.z))continue;seen.add(n);queue.push(n);}}this.reachable=queue.map(point);for(let q=0;q<4;q++){const pool=this.reachable.filter(p=>this.quadrant(p)===q&&Math.abs(p.x)>8&&Math.abs(p.z)>7&&Math.abs(p.x)<37&&Math.abs(p.z)<37&&Math.hypot(p.x,p.z-26)>14&&!collision(p.x,p.z,.7));const chosen=[];for(const p of this.shuffle(pool))if(chosen.every(b=>Math.hypot(p.x-b.x,p.z-b.z)>7)){chosen.push(p);if(chosen.length===7)break;}if(chosen.length<4)throw new Error('安全な配置地点を確保できません');this.candidates.push(...chosen.map(p=>({...p,quadrant:q})));}}
 quadrant(p){return (p.x>=0?1:0)+(p.z>=0?2:0);}
 shuffle(a){const out=[...a];for(let i=out.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[out[i],out[j]]=[out[j],out[i]];}return out;}
 layout(){const items=[],cells=[];for(let q=0;q<4;q++){const pool=this.shuffle(this.candidates.filter(p=>p.quadrant===q));items.push(pool[0]);cells.push(pool.find(p=>Math.hypot(p.x-pool[0].x,p.z-pool[0].z)>7));}return {items:this.shuffle(items),cells};}
 enemySpawn(items){const pool=this.reachable.filter(p=>Math.hypot(p.x,p.z-26)>30&&items.every(i=>Math.hypot(i.x-p.x,i.z-p.z)>9));return pool[Math.floor(Math.random()*pool.length)]||{x:0,z:-8};}
}
class BatterySystem {
 constructor(){this.items=[];this.reset();const mat=material(0xbba777,{metalness:.5,roughness:.4,emissive:0x8e7545,emissiveIntensity:.65});for(let i=0;i<4;i++){const g=new THREE.Group();for(const x of [-.12,.12]){const m=new THREE.Mesh(new THREE.CylinderGeometry(.1,.1,.42,10),mat);m.position.x=x;g.add(m);}g.position.y=.3;scene.add(g);this.items.push({x:0,z:0,group:g,found:false});}}
 reset(){this.value=100;this.blackout=-1;this.warned=false;this.reserve=0;this.cause=false;if($('battery-dark'))$('battery-dark').style.opacity=0;}
 place(points){this.items.forEach((p,i)=>{Object.assign(p,points[i],{found:false});p.group.position.set(p.x,.3,p.z);p.group.visible=true;});}
 add(amount=35){this.value=Math.min(100,this.value+amount);flashOn=this.value>0;this.blackout=-1;this.warned=false;$('battery-dark').style.opacity=0;}
 update(dt){flashOn=this.value>0;if(this.value>0)this.value=Math.max(0,this.value-dt*.55);if(this.value<20&&!this.warned){this.warned=true;toast('ライトの電池が残り少ない。予備の電池を探そう。',4);}if(this.value===0){if(this.reserve>0){this.reserve--;this.add();}else{if(this.blackout<0){this.blackout=0;flashOn=false;$('light').classList.remove('active');toast('……灯りが、消えた。',4);}const previous=this.blackout;this.blackout+=dt;$('battery-dark').style.opacity=String(clamp((this.blackout-1)/2,0,.98));if(previous<3&&this.blackout>=3)audio.tone(48,3,.2,'sine',26);if(previous<5&&this.blackout>=5)audio.step(true);if(this.blackout>=8){this.cause=true;endGame(false);}}}flash.visible=flashOn&&this.value>0;flash.intensity=!settings.gentle&&this.value>0&&this.value<12&&Math.sin(elapsed*29)>.9?12:36;$('battery-value').textContent=Math.ceil(this.value).toString().padStart(3,'0');$('battery-fill').style.width=this.value+'%';$('battery-fill').style.background=this.value<20?'#b95f50':'#b4bf9e';for(const p of this.items)if(!p.found){p.group.rotation.y=0;p.group.position.y=.23;}}
}
class FaceVariants {
 constructor(){this.textures=[];this.index=0;}
 async load(){const legacy=await new THREE.TextureLoader().loadAsync(FACE);legacy.colorSpace=THREE.SRGBColorSpace;this.textures.push(legacy);for(const src of EXTRA_FACES){const im=await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=reject;i.src=src;});const c=document.createElement('canvas');c.width=c.height=512;const ctx=c.getContext('2d');ctx.drawImage(im,0,0,512,512);const data=ctx.getImageData(0,0,512,512),a=data.data,q=[],seen=new Uint8Array(512*512);for(let x=0;x<512;x++)q.push(x,511*512+x);for(let y=1;y<511;y++)q.push(y*512,y*512+511);for(let h=0;h<q.length;h++){const p=q[h];if(seen[p])continue;seen[p]=1;const i=p*4;if(Math.min(a[i],a[i+1],a[i+2])<218)continue;a[i+3]=0;const x=p%512,y=p>>9;if(x>0)q.push(p-1);if(x<511)q.push(p+1);if(y>0)q.push(p-512);if(y<511)q.push(p+512);}ctx.putImageData(data,0,0);const tex=new THREE.CanvasTexture(c);tex.colorSpace=THREE.SRGBColorSpace;this.textures.push(tex);}}
 select(){this.index=settings.defaultFace?0:Math.floor(Math.random()*5);enemyMesh.material.map=this.textures[this.index];enemyMesh.material.needsUpdate=true;$('scare').querySelector('img').src=this.index?EXTRA_FACES[this.index-1]:FACE;}
}
const classicBase={init,startGame,updatePlayer,updateEnemy,getInteraction,interact,toggleLight,endGame,returnHome,revealGameOver};
let classic=null;
init=async function(){await classicBase.init();if(!ready)return;ready=false;$('start').disabled=true;try{const spawns=new SpawnManager(),battery=new BatterySystem(),faces=new FaceVariants();await faces.load();classic={spawns,battery,faces};const row=document.createElement('div');row.className='setting';row.innerHTML='<div class="setting-line"><span>デフォルトの顔のみ</span><button id="default-face" class="toggle" role="switch" aria-label="デフォルトの顔のみ"></button></div><p class="small-note">OFF：探索を始めるたびに5種類から選ばれます。</p>';$('quality').closest('.setting').after(row);$('default-face').setAttribute('aria-checked',String(settings.defaultFace));$('default-face').onclick=()=>{settings.defaultFace=!settings.defaultFace;$('default-face').setAttribute('aria-checked',String(settings.defaultFace));saveSettings();if(settings.defaultFace)faces.select();};ready=true;$('start').disabled=false;$('load-message').textContent='CLASSIC SURVIVAL · OFFLINE READY';}catch(e){show('fatal');$('fatal-detail').textContent='素材・配置の準備に失敗しました。 '+e.message;}};
startGame=function(){if(!ready||!classic)return;const layout=classic.spawns.layout();parts.forEach((p,i)=>{Object.assign(p,layout.items[i]);p.group.position.set(p.x,.8,p.z);});classic.battery.reset();classic.battery.place(layout.cells);classicBase.startGame();Object.assign(enemy,classic.spawns.enemySpawn(layout.items));classic.faces.select();classic.battery.update(0);toast('7つの部品とライト用電池を探そう。帰り道は南の鳥居。',6);};
getInteraction=function(){const hit=classicBase.getInteraction();if(hit?.type==='part'&&!clearLine(player.x,player.z,hit.p.x,hit.p.z))return null;if(hit)return hit;if(classic)for(const p of classic.battery.items)if(!p.found&&Math.hypot(player.x-p.x,player.z-p.z)<2.3&&clearLine(player.x,player.z,p.x,p.z))return {type:'cell',p};return null;};
interact=function(){if(state!=='playing')return;const hit=getInteraction();if(hit?.type==='cell'){if(classic.battery.value>=99){toast('電池はまだ十分だ。',2);return;}hit.p.found=true;hit.p.group.visible=false;classic.battery.add();audio.pickup();toast('ライト用電池を補充した。 +35',3);}else classicBase.interact();};
updatePlayer=function(dt){classicBase.updatePlayer(dt);if(!classic)return;classic.battery.update(dt);if(state==='playing'){const hit=getInteraction();show('interaction');$('interaction').disabled=!hit;$('interaction').textContent=!hit?'取得 / E':hit.type==='cell'?'電池 +35 を拾う':$('interaction').textContent;}};
updateEnemy=function(dt){if(classic?.battery.blackout>=0){chaseMusic.stop(false);return 0;}return classicBase.updateEnemy(dt);};
toggleLight=function(){flashOn=(classic?.battery.value??100)>0;};
endGame=function(won){$('battery-dark').style.opacity=0;classicBase.endGame(won);};
returnHome=function(){classic?.battery.reset();classicBase.returnHome();};
revealGameOver=function(){classicBase.revealGameOver();if(classic?.battery.cause)$('death-summary').textContent='灯りを失い、闇に呑まれた。　·　'+formatTime(elapsed)+'　·　部品 '+partsFound+'/7';};

