 update(danger){const visible=state==='playing'&&!settings.gentle&&danger>0;if(!visible){this.clear();return;}this.canvas.style.opacity=String(danger*(.21+.06*Math.random()));if(elapsed<this.next)return;this.next=elapsed+.13-.065*danger;const a=this.data.data;for(let i=0;i<a.length;i+=4){const v=Math.random()*255;a[i]=a[i+1]=a[i+2]=v;a[i+3]=Math.random()<.04+danger*.12?230:70+danger*40;}this.ctx.putImageData(this.data,0,0);}
