const sevenBase={init,startGame,updateEnemy,getInteraction,interact,endGame,pauseGame,openModal,returnHome,updateHUD};
function pickLegacyFace(r=Math.random()){return r<.4?0:r<.55?1:r<.7?2:r<.85?3:4;}
const oldFaceLoad=FaceVariants.prototype.load;
