 start(){const a=this.spawns.layout();classicBase.startGame();parts.forEach((p,i)=>{Object.assign(p,a.items[i]);p.group.position.set(p.x,this.map.floor(p.x,p.z)+.42,p.z);});classic.battery.reset();classic.battery.place(a.cells);seven.lock.reset(a.key);buildNav();seven.lock.gate.position.set(0,this.map.floor(0,44.5),44.5);Object.assign(enemy,a.enemy);classic.faces.select();this.ai.reset();classic.battery.update(0);player.x=0;player.z=32;this.map.lastArea='';updateHUD();toast('旅行の帰り道、バイクが故障した。廃屋や神社に使える部品が残っているかもしれない。',8);}
