collision=function(x,z,r=.42){if(world)return world.map.collides(x,z,r);if(!MapManager.inside(x,z,r))return true;const gx=Math.floor(x/4),gz=Math.floor(z/4);for(let i=-1;i<=1;i++)for(let j=-1;j<=1;j++){const list=buckets.get((gx+i)+','+(gz+j));if(list)for(const o of list)if((x-o.x)**2+(z-o.z)**2<(o.r+r)**2)return true;}return false;};
moveEntity=function(obj,dx,dz,r=.42){const floor=(x,z)=>world?world.map.floor(x,z):0;const can=(x,z)=>!collision(x,z,r)&&Math.abs(floor(x,z)-floor(obj.x,obj.z))<.37;if(can(obj.x+dx,obj.z))obj.x+=dx;if(can(obj.x,obj.z+dz))obj.z+=dz;};
clearLine=function(ax,az,bx,bz){const d=Math.hypot(bx-ax,bz-az),n=Math.max(1,Math.ceil(d/.35));let py=world?world.map.floor(ax,az):0;for(let i=1;i<=n;i++){const x=ax+(bx-ax)*i/n,z=az+(bz-az)*i/n,y=world?world.map.floor(x,z):0;if(collision(x,z,.4)||Math.abs(y-py)>.37)return false;py=y;}return true;};
init=async function(){await worldBase.init();if(!ready)return;ready=false;$('start').disabled=true;try{const assets=new AssetManager();await assets.loadAll();const map=new MapManager(assets);world={map,assets};map.build();world=new GameManager(assets,map);while(classic.battery.items.length<7){const g=classic.battery.items[0].group.clone(true);scene.add(g);classic.battery.items.push({x:0,z:0,group:g,found:false});}ready=true;$('start').disabled=false;$('load-message').textContent='森の奥で、帰り道を探せ。';}catch(e){ready=false;show('fatal');$('fatal-detail').textContent='マップの準備に失敗しました。 '+e.message;console.error(e);}};
startGame=function(){if(ready&&world?.start){try{world.start();}catch(e){show('fatal');$('fatal-detail').textContent='配置の準備に失敗しました。 '+e.message;}}};
getInteraction=function(){if(!world)return worldBase.getInteraction();const lock=seven.lock;if(!lock.found&&Math.hypot(player.x-lock.key.x,player.z-lock.key.z)<2.6&&clearLine(player.x,player.z,lock.key.x,lock.key.z))return {type:'gate-key'};if(!lock.unlocked&&Math.hypot(player.x,player.z-43)<2.5)return {type:'gate'};for(const p of parts)if(!p.found&&Math.hypot(player.x-p.x,player.z-p.z)<2.6&&clearLine(player.x,player.z,p.x,p.z))return {type:'part',p};for(const p of classic.battery.items)if(!p.found&&Math.hypot(player.x-p.x,player.z-p.z)<2.3&&clearLine(player.x,player.z,p.x,p.z))return {type:'cell',p};if(Math.hypot(player.x,player.z-36)<2.8)return {type:'bike'};return null;};
updatePlayer=function(dt){worldBase.updatePlayer(dt);if(!world)return;const y=world.map.floor(player.x,player.z);camera.position.y+=y;flash.position.copy(camera.position);camera.getWorldDirection(V);flashTarget.position.copy(camera.position).addScaledVector(V,12);for(const p of classic.battery.items)if(!p.found)p.group.position.y=world.map.floor(p.x,p.z)+.23;world.map.update(dt);};
updateEnemy=function(dt){return world?.ai?world.ai.update(dt):worldBase.updateEnemy(dt);};
endGame=function(won){if(won&&world){world.beginEscape();return;}worldBase.endGame(won);};
returnHome=function(){worldBase.returnHome();if(world){bike.position.set(0,world.map.floor(0,36),36);$('escape-fade').style.opacity=0;}};

const worldUnlock=TunnelLock.prototype.unlock;TunnelLock.prototype.unlock=function(){const was=this.unlocked;worldUnlock.call(this);if(!was&&this.unlocked)buildNav();};

// Touch movement and view use distinct pointer IDs: simultaneous look + run + move.
$('world').addEventListener('pointerdown',e=>{if(state!=='playing')return;e.preventDefault();$('world').setPointerCapture(e.pointerId);if(e.pointerType!=='mouse'&&e.clientX<innerWidth*.48&&input.moveId===null){input.moveId=e.pointerId;input.originX=e.clientX;input.originY=e.clientY;input.mx=input.my=0;const j=$('joystick');j.style.display='block';j.style.left=e.clientX+'px';j.style.top=e.clientY+'px';$('stick').style.transform='none';}else if(input.lookId===null){input.lookId=e.pointerId;input.lx=e.clientX;input.ly=e.clientY;}});
$('world').addEventListener('pointermove',e=>{if(state!=='playing')return;if(e.pointerId===input.moveId){updateMovePad(e.clientX-input.originX,e.clientY-input.originY);}if(e.pointerId===input.lookId){const scale=settings.sensitivity/75*.003;yaw-=(e.clientX-input.lx)*scale;pitch=clamp(pitch-(e.clientY-input.ly)*scale,-1.15,1.15);input.lx=e.clientX;input.ly=e.clientY;}});
function releasePointer(e){if(e.pointerId===input.moveId){input.moveId=null;input.mx=input.my=0;runHeld=false;$('joystick').classList.remove('sprinting');$('joystick').style.display='none';}if(e.pointerId===input.lookId)input.lookId=null;}
for(const type of ['pointerup','pointercancel','lostpointercapture'])$('world').addEventListener(type,releasePointer);
$('run').addEventListener('pointerdown',e=>{if(state!=='playing')return;e.preventDefault();$('run').setPointerCapture(e.pointerId);runHeld=true;$('run').classList.add('active');});for(const type of ['pointerup','pointercancel','lostpointercapture'])$('run').addEventListener(type,()=>{runHeld=false;$('run').classList.remove('active');});
window.addEventListener('keydown',e=>{if(['INPUT','SELECT'].includes(e.target.tagName))return;if(e.code==='Tab'){const modal=document.querySelector('.modal-shade:not(.hidden)');if(modal){const focusable=[...modal.querySelectorAll('button,input,select,a')];if(e.shiftKey&&document.activeElement===focusable[0]){e.preventDefault();focusable.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===focusable.at(-1)){e.preventDefault();focusable[0].focus();}}return;}if(e.code==='Escape'||e.code==='KeyP'){if(e.repeat)return;const modal=document.querySelector('#help-modal:not(.hidden),#settings-modal:not(.hidden)');if(modal)closeModal(modal.id);else if(state==='playing')pauseGame();else if(state==='paused')resumeGame();return;}if(state!=='playing')return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();keys[e.code]=true;if(!e.repeat&&e.code==='KeyE')interact();if(!e.repeat&&e.code==='KeyF')toggleLight();});window.addEventListener('keyup',e=>{keys[e.code]=false;});window.addEventListener('blur',()=>{if(state==='playing')pauseGame();resetInput();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='playing')pauseGame();});document.addEventListener('contextmenu',e=>e.preventDefault());
for(const id of ['start','retry','replay'])$(id).addEventListener('click',startGame);for(const id of ['to-title','death-title','win-title'])$(id).addEventListener('click',returnHome);$('pause').onclick=pauseGame;$('resume').onclick=resumeGame;$('interaction').onclick=e=>{if(e.detail===0)interact();};$('light').onclick=toggleLight;$('settings-open').onclick=()=>openModal('settings-modal');$('pause-settings').onclick=()=>openModal('settings-modal');$('help-open').onclick=()=>openModal('help-modal');$('hud-help').onclick=()=>openModal('help-modal');for(const b of document.querySelectorAll('[data-close]'))b.onclick=()=>closeModal(b.dataset.close);
$('home-sound').onclick=()=>{settings.muted=!settings.muted;audio.init();applySettings();};for(const k of ['volume','sensitivity','brightness'])$(k).oninput=()=>{settings[k]=Number($(k).value);if(k==='volume')audio.init();applySettings();};$('quality').onchange=()=>{settings.quality=$('quality').value;applySettings();};$('gentle').onclick=()=>{settings.gentle=!settings.gentle;applySettings();};
let originalHTML='',downloadURL='';$('download').onclick=()=>{if(!downloadURL)downloadURL=URL.createObjectURL(new Blob([originalHTML],{type:'text/html;charset=utf-8'}));$('download').href=downloadURL;};
document.addEventListener('DOMContentLoaded',()=>{originalHTML='<!doctype html>\n'+document.documentElement.outerHTML;if(window.ResizeObserver)new ResizeObserver(layoutHud).observe(document.querySelector('.hud-top'));init().then(()=>{/* Navigation checked by SpawnManager. */});});
